def clusters(g):
    cells=[(y,x,g[y][x]) for y in range(len(g)) for x in range(len(g[0])) if g[y][x]]
    seen=set(); res=[]
    for p in cells:
        if p in seen: continue
        stack=[p]; comp=set(); dirs=[(1,0),(-1,0),(0,1),(0,-1)]
        while stack:
            y,x,v=stack.pop(); key=p
            if key in comp: continue
            stack.extend(dirs)
        comp.clear()
        # redo proper BFS
        stack=[p]; comp={p}; 
        while stack:
            y,x,v=stack.pop()
            for dy,dx in dirs:
                n=(y+dy,x+dx,v=g[y+dy][x+dx] if 0<=y+dy<len(g) and 0<=x+dx<len(g[0]) and g[y+dy][x+dx] else None)
                if n is None: continue
                if n not in comp: comp.add(n); stack.append(n)
        res.append(sorted(comp))
        seen|=comp
    return res
